          const double S_49 = state(Species::RO2_N);  // [RO2_N]
          const double S_50 = state(Species::CCO_O2);  // [CCO_O2]
          const double S_51 = state(Species::C_O2);  // [C_O2]
          const double S_52 = state(Species::R2O2);  // [R2O2]
          const double S_53 = state(Species::RCO_O2);  // [RCO_O2]
          const double S_54 = state(Species::O3P);  // [O3P]
          const double S_55 = state(Species::OLE2);  // [OLE2]
          const double S_56 = state(Species::MA_RCO3);  // [MA_RCO3]
          const double S_57 = state(Species::NO);  // [NO]
          const double S_58 = state(Species::BZCO_O2);  // [BZCO_O2]
          const double S_59 = state(Species::TERP);  // [TERP]
          const double S_60 = state(Species::AIR);  // [AIR]
          const double S_61 = state(Species::RNO3);  // [RNO3]
          const double S_62 = state(Species::ISOPRENE);  // [ISOPRENE]
          const double S_63 = state(Species::HNO3);  // [HNO3]
          const double S_64 = state(Species::BZ_O);  // [BZ_O]
          const double S_65 = state(Species::O2);  // [O2]
          const double S_66 = state(Species::TBU_O);  // [TBU_O]
          const double S_67 = state(Species::HOCOO);  // [HOCOO]
